let products=[],filter='Tous',query='';const grid=document.querySelector('#products'),dialog=document.querySelector('#detail');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function packshot(p,lazy=true){return `<div class="packshot ${p.package}" role="img" aria-label="Présentation ${esc(p.name)}, ${p.size}"><img class="package-base" src="assets/package-${p.package}.webp" alt="" ${lazy?'loading="lazy"':''}><div class="package-label"><img src="${p.front}" alt="Étiquette ${esc(p.name)}" ${lazy?'loading="lazy"':''}></div><span class="package-volume">${p.size}</span></div>`;}
function render(){const list=products.map((p,i)=>({...p,i})).filter(p=>(filter==='Tous'||p.cat===filter)&&(p.name+' '+p.sub+' '+p.cat).toLocaleLowerCase('fr').includes(query));grid.innerHTML=list.map(p=>`<article class="card"><button class="card-image" data-open="${p.i}" aria-label="Découvrir ${esc(p.name)}"><span class="product-state">${p.state}</span>${packshot(p)}</button><div class="card-content"><p class="category">${p.cat}</p><h3>${p.name}</h3><p class="card-sub">${p.sub}</p><p class="card-desc">${p.desc}</p><div class="card-basis"><span>À BASE DE</span><p>${p.basis}</p></div><div class="card-meta"><span>${p.uses[0][0]}</span><span>${p.size}</span></div><button class="product-action" data-open="${p.i}">Découvrir la fiche <span>→</span></button></div></article>`).join('');document.querySelector('#empty').hidden=list.length>0;document.querySelector('#result-count').textContent=list.length+' solution'+(list.length>1?'s':'')+' agricole'+(list.length>1?'s':'');}
function setFilter(value){filter=value;document.querySelectorAll('[data-filter]').forEach(x=>{const on=x.dataset.filter===value;x.classList.toggle('active',on);x.setAttribute('aria-pressed',String(on))});render();}
function openProduct(i){const p=products[i];if(!p)return;document.querySelector('#detail-content').innerHTML=`<div class="detail-grid"><div class="detail-visual">${packshot(p,false)}<span>${p.size} · ${p.state}</span><a href="${p.pdf}" target="_blank" rel="noopener">Voir l’étiquette complète en PDF →</a></div><div class="detail-summary"><p class="eyebrow">BIOJOUD / ${p.cat}</p><h2 id="product-title">${p.name}</h2><h3>${p.sub}</h3><p>${p.desc}</p><div class="basis-explainer"><span>CE QUI COMPOSE LE PRODUIT</span><h4>${p.basis}</h4><p>${p.basisDetail}</p></div><ul class="benefit-list">${p.benefits.map(x=>`<li>${x}</li>`).join('')}</ul><div class="detail-buttons"><button class="button gold" data-quote="${i}">Demander un devis →</button><a class="button outline" href="${p.pdf}" target="_blank" rel="noopener">Étiquette PDF ↓</a></div><button class="share-product button outline" data-share="${i}">Partager cette fiche</button><p class="source-note">Informations transcrites de l’étiquette BIOJOUD. Les bénéfices présentés sont ceux indiqués par le fabricant.</p></div></div><div class="technical"><section><p class="eyebrow">01 / COMPOSITION</p><h3>Ce que contient la formulation</h3><table><tbody>${p.composition.map(r=>`<tr><th scope="row">${r[0]}</th><td>${r[1]}</td></tr>`).join('')}</tbody></table><p class="physical">${p.physical}</p></section><section><p class="eyebrow">02 / APPLICATION</p><h3>Modes d’emploi et doses</h3>${p.uses.map(r=>`<div class="dose"><div><b>${r[0]}</b><strong>${r[1]}</strong></div><p>${r[2]}</p></div>`).join('')}<p class="source-note">Doses reprises de l’étiquette, à adapter avec BIOJOUD selon la culture et les conditions d’application. L’étiquette complète reste la référence.</p></section><section><p class="eyebrow">03 / CULTURES</p><h3>Domaines d’utilisation</h3><p>${p.cultures}</p></section><section><p class="eyebrow">04 / CONSERVATION</p><h3>Stockage & compatibilité</h3><p>${p.storage}</p><p>${p.compatibility}</p></section></div><div class="safety"><strong>Précautions d’emploi</strong><p>Usage agricole. Tenir hors de portée des enfants. Éviter le contact avec les yeux et la peau. Porter les équipements de protection indiqués sur l’étiquette. Ne pas ingérer. Lire toutes les précautions et restrictions avant utilisation.</p></div><details class="label-preview"><summary>Consulter l’étiquette originale</summary><a href="${p.pdf}" target="_blank" rel="noopener"><img src="${p.label}" alt="Étiquette originale complète ${p.name}" loading="lazy"></a></details>`;dialog.showModal();dialog.scrollTop=0;}
fetch('products.json?v=7').then(r=>{if(!r.ok)throw Error();return r.json()}).then(p=>{products=p;render();const select=document.querySelector('#contact-product');p.forEach(x=>{const o=document.createElement('option');o.value=x.name;o.textContent=x.name+' — '+x.size;select.append(o)});setFilter('Tous');const key=new URLSearchParams(location.search).get('produit');const idx=products.findIndex(x=>x.name===key);if(idx>=0)openProduct(idx);const request=new URLSearchParams(location.search).get('demande');if(request&&products.some(x=>x.name===request)){select.value=request;document.querySelector('#contact').scrollIntoView()}}).catch(()=>grid.innerHTML='<p>Le catalogue est momentanément indisponible. Contactez-nous par e-mail pour les fiches produits.</p>');
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open)openProduct(+open.dataset.open);const b=e.target.closest('[data-filter]');if(b)setFilter(b.dataset.filter);const link=e.target.closest('[data-category-link]');if(link)setFilter(link.dataset.categoryLink);const quote=e.target.closest('[data-quote]');if(quote){document.querySelector('#contact-product').value=products[+quote.dataset.quote].name;dialog.close();document.querySelector('#contact').scrollIntoView({behavior:'smooth'});document.querySelector('[name="nom"]').focus({preventScroll:true})}});
document.querySelector('.search input').addEventListener('input',e=>{query=e.target.value.trim().toLocaleLowerCase('fr');render()});document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});const menu=document.querySelector('.menu');menu.onclick=()=>{const n=document.querySelector('nav');n.classList.toggle('open');menu.setAttribute('aria-expanded',n.classList.contains('open'))};document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.querySelector('#year').textContent=new Date().getFullYear();
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);const subject='Contact BIOJOUD — '+(d.get('produit')||'BIOJOUD');const body='Bonjour BIOJOUD,\n\n'+d.get('message')+'\n\nNom : '+d.get('nom')+'\nE-mail : '+d.get('email')+'\nProduit : '+(d.get('produit')||'À conseiller')+'\n\nMerci.';window.location.href='mailto:biojoudmaroc@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#contact-status').textContent='Votre demande est préparée. Envoyez-la depuis votre application e-mail. Si elle ne s’ouvre pas, écrivez directement à biojoudmaroc@gmail.com.';});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-share]');if(!b)return;const u=new URL(location.href);u.searchParams.set('produit',products[+b.dataset.share].name);u.hash='';try{await navigator.clipboard.writeText(u.href);b.textContent='Lien copié';}catch{b.textContent='Copier le lien';const a=document.createElement('input');a.value=u.href;a.readOnly=true;b.after(a);a.select();}});
